 function observationOptions(){const rows=[['world','旧市街'],['room','六畳間'],['workshop','研究院の工房']];if(state.narrative.step>=21)rows.push(['factory','第一魔導工房']);if(state.narrative.step>=22)rows.push(['district','南部の工房地区']);if(state.narrative.step>=27)rows.push(['academy','若い発明家の研究院']);if(state.narrative.step>=30)rows.push(['newcity','西側の新都市']);if(state.narrative.step>=33)rows.push(['institute','神殿研究院の書庫']);if(state.narrative.step>=36)rows.push(['assembly','研究院の討論会場']);if(state.narrative.step>=41)rows.push(['geography','地理学部門']);if(state.narrative.step>=43)rows.push(['expedition',state.narrative.step>=44?'探査風景（記録）':'調査隊']);if(state.narrative.step>=47)rows.push(['river',state.narrative.step>=50?'魔導船（渡河の記録）':'蒼流河の魔導船']);if(state.narrative.step>=49)rows.push(['contact','最初の対話']);if(state.narrative.step>=51)rows.push(['forest','森の集落']);if(state.narrative.step>=56)rows.push(['sharedAssembly','人類と森の民の大講堂']);if(state.narrative.step>=58)rows.push(['festival',state.narrative.step>=62?'共同体成立の祭り':'共通暦の祭り']);if(state.narrative.step>=65)rows.push(['neoLiving','新都市の暮らし']);if(state.narrative.step>=67)rows.push(['model','創世都市の模型']);if(state.narrative.step>=72)rows.push(['beast','獣人の集落']);if(state.narrative.step>=75)rows.push(['defense','北方防衛戦（記録）']);if(state.narrative.step>=79)rows.push(['audience',state.narrative.step>=81?'友好の握手':'狩人王との会談']);if(state.narrative.step>=86&&state.story.read.includes('story.arcadia.western_ocean'))rows.push(['ocean','西方大海の発見']);if(state.narrative.step>=92&&state.story.read.includes('story.arcadia.dwal_city'))rows.push(['underground','地下都市の記録']);return rows;}
 function chooseSurveyPoint(id){
  if(!playing||modalOpen()||!E.surveyStatus(state).enabled)return;stop('測量図を確かめています。');
  if(!surveyStart){surveyStart=id;surveyMessage='もう一つの基準点を選んでください。';renderScholars();}
  else if(surveyStart===id){surveyStart=null;surveyMessage='基準点を選び直せます。';renderScholars();}
  else{const from=surveyStart;surveyStart=null;try{const routes=E.surveyStatus(state).routes;state=E.measureRoute(state,from,id,state.revision);const route=routes.find(x=>(x.from===from&&x.to===id)||(x.to===from&&x.from===id));surveyMessage=route.title+'：'+route.units+'目盛りを記録しました。';render();recovery();showEvent();}catch(e){surveyMessage=e.message;renderScholars();}}
  if(!modalOpen())$('surveyPoint-'+id)?.focus({preventScroll:true});
 }
 function renderExpedition(){
  const x=E.expeditionStatus(state);$('expeditionPanel').hidden=!x.available||!['world','geography','expedition'].includes(view);$('expeditionProgress').textContent=`探査資料の整理 ${state.expedition.filed.length} / 3`;
  const phase=String(state.narrative.step);if($('expeditionDetails').dataset.phase!==phase){$('expeditionDetails').open=state.narrative.step===43;$('expeditionDetails').dataset.phase=phase;}
  $('expeditionRecords').replaceChildren(...x.records.map(r=>{const box=node('section',undefined,'network-card'),b=node('button',r.title+(r.filed?' · 整理済み':''));b.dataset.expeditionRecord=r.id;b.disabled=!x.enabled||r.filed;b.setAttribute('aria-pressed',String(archiveSelection===r.id));b.onclick=()=>{if(modalOpen())return;stop('探査資料を確かめています。');archiveSelection=r.id;archiveMessage=r.text+' 対応する記録を選んでください。';renderExpedition();document.querySelector('[data-expedition-record="'+r.id+'"]').focus({preventScroll:true});};box.append(b,node('p',r.text));return box;}));
  $('archiveCategories').replaceChildren(...x.categories.map(c=>{const b=node('button',c.title);b.dataset.archiveCategory=c.id;b.disabled=!x.enabled||!archiveSelection;b.onclick=()=>{if(modalOpen())return;const id=archiveSelection;try{state=E.fileExpedition(state,id,c.id,state.revision);archiveSelection=null;archiveMessage=state.expedition.filed.length===3?'三つの代表資料を整理しました。帰還と集約は次の場面で見届けます。':'資料を整理しました。次の資料を確かめられます。';render();recovery();showEvent();if(!modalOpen())document.querySelector('[data-expedition-record]:not(:disabled)')?.focus({preventScroll:true});}catch(e){archiveMessage=e.message;renderExpedition();document.querySelector('[data-archive-category="'+c.id+'"]').focus({preventScroll:true});}};return b;}));
  $('expeditionFeedback').textContent=(state.narrative.step>=44?'三つの資料は、帰還後の記録に残っています。':archiveMessage)||(x.enabled?'資料を一つ選ぶと、記録の種類を選べます。':'整理した資料は、旅の記録として残っています。');
 }
 function contactIcon(id){const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox','0 0 64 64');svg.setAttribute('aria-hidden','true');const shapes={sun:'<circle cx="32" cy="32" r="12"/><path d="M32 5v8M32 51v8M5 32h8M51 32h8M13 13l6 6M45 45l6 6M13 51l6-6M45 19l6-6"/>',river:'<path d="M5 18Q16 9 27 18T59 18M5 32Q16 23 27 32T59 32M5 46Q16 37 27 46T59 46"/>',boat:'<path d="M8 33h48l-9 15H20Z M20 33V20h24v13M5 54q10-6 20 0t20 0t14 0"/>',smile:'<circle cx="32" cy="18" r="12"/><path d="M27 21q5 5 10 0M28 15h1M36 15h1M32 30v16M16 35l16 4 16-4M32 46l-13 13M32 46l13 13"/>'};svg.innerHTML='<g fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round">'+(shapes[id]||'')+'</g>';return svg;}
 function renderContact(){
  const x=E.contactStatus(state);$('contactPanel').hidden=!x.available||!['world','contact','forest'].includes(view);$('contactProgress').textContent=`対話の紙片 ${state.contact.drawn.length} / 4`;
  const phase=String(state.narrative.step);if($('contactDetails').dataset.phase!==phase){$('contactDetails').open=state.narrative.step===49;$('contactDetails').dataset.phase=phase;}
  $('contactPaper').replaceChildren(...state.contact.drawn.map(id=>{const item=x.symbols.find(s=>s.id===id),f=node('figure');f.dataset.drawnSymbol=id;f.append(contactIcon(id),node('figcaption',item.title));return f;}));
  $('contactSymbols').replaceChildren(...x.symbols.map(item=>{const box=node('section',undefined,'network-card'),b=node('button',item.title+(item.drawn?' · 記録済み':'を描く'));b.prepend(contactIcon(item.id));b.dataset.contactSymbol=item.id;b.disabled=!x.enabled||item.drawn;b.onclick=()=>{if(modalOpen())return;stop('最初の対話を見守っています。');try{state=E.drawContact(state,item.id,state.revision);render();recovery();showEvent();if(!modalOpen())document.querySelector('[data-contact-symbol]:not(:disabled)')?.focus({preventScroll:true});}catch(e){tell(e.message);}};box.append(b,node('p',item.text));return box;}));
  $('contactReply').textContent=x.replied?'森・集落・人々、そして笑顔の絵が返ってきた。言葉の全てが通じたわけではない。':'四つの絵を確かめた後、相手から返ってきた絵を見届けられます。';
  const wordsKnown=state.story.read.includes('story.arcadia.first_shared_words'),westKnown=state.story.read.includes('story.arcadia.further_west');$('sharedWords').textContent=wordsKnown?'三か月の交流で覚え始めた単語：水・火・空・森。'+(westKnown?'「オウ」は未解読の言葉として残る。':''):'共通の言葉はまだ少ない。名前や単語は、その先の交流の中で知っていく。';
 }
