  if(library==='people'&&state.campaign){$('libraryTitle').textContent='人物と継承の記録';const c=RokujoCampaign.status(state.campaign);for(const p of (c.knownPeople.length?c.knownPeople:c.people)){const el=node('section',undefined,'research-node');el.append(node('h3',p.name),node('p',p.state),node('blockquote',p.evidence));content.append(el);}if(c.completed>=270)content.append(node('p','ガルド：第270話で逝去、享年八十四。資料を残し、ガルドOSの意味は未解明のまま受け継がれた。'));return;}
