   if(state.narrative.step>=121&&state.story.read.includes('story.arcadia.first_words')){const el=node('section',undefined,'entry-card'),im=node('img');el.dataset.person='seira';im.src='../画像/actors/actor.seira.harbor_supervisor.v1.png';im.className='journal-portrait';im.alt='セイラ・港湾都市セレスの監督官';im.style.height=(130*1*1536/1517).toFixed(1)+'px';im.onerror=()=>{im.hidden=true;};el.append(im,node('h3','セイラ'),node('p',state.narrative.step>=122&&state.story.read.includes('story.arcadia.maresia')?'マレシア王国の港湾都市セレスの監督官。青い外套に銀色の装飾。探査隊を都市へ招き、地図を広げて国の名を教えた。':'港湾都市セレスの監督官。青い外套に銀色の装飾。海を渡ってきた探査隊と、最初に言葉を交わした。'));content.append(el);}
   if(state.narrative.step>=96&&state.story.read.includes('story.arcadia.queen_milena')){const el=node('section',undefined,'entry-card'),im=node('img');el.dataset.person='milena';im.src='../画像/actors/actor.milena.queen.v1.png';im.className='journal-portrait';im.alt='ミレナ女王・地下王国ドワルドの女王';im.style.height=(130*0.8*1536/1508).toFixed(1)+'px';im.onerror=()=>{im.hidden=true;};el.append(im,node('h3','ミレナ女王'),node('p',state.narrative.step>=101&&state.story.read.includes('story.arcadia.exchange_pact')?'地下王国ドワルド第三十七代女王。銀色の髪と深紅の瞳、結晶の冠。アルカディアと技術交流協定を結んだ。':state.narrative.step>=97&&state.story.read.includes('story.arcadia.four_way_banquet')?'地下王国ドワルド第三十七代女王。銀色の髪と深紅の瞳、結晶の冠。晩餐会で、地上と地下は友になろうと語った。':'地下王国ドワルド第三十七代女王。銀色の髪と深紅の瞳、結晶の冠。王宮でアリアたちを迎えた。'));content.append(el);}
   for(const life of state.lifeLedger){const el=node('section',undefined,'entry-card');el.dataset.life=life.lifeId;el.append(node('h3',life.status==='current'?'アリアの今の人生':'アリアの前の人生'),node('p',life.memories.length?'残る記憶：'+life.memories.join('、'):'まだ記録された出来事はありません。'));content.append(el);}
