 function exportRaw(raw,name){const blob=new Blob([raw],{type:'application/json'}),url=URL.createObjectURL(blob),a=node('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000);}
 function exportCurrent(){if(!playing)return;try{exportRaw(repo.exportState(state),`rokujo-${state.world.tick}-tick.json`);tell('JSONを書き出しました。同じファイルから世界を再開できます。');}catch(e){tell(e.message);}}
 function openRecords(exitAfter=false){if(modalOpen())return;stop('保存・再開を確認しています。');leaveAfterSave=exitAfter;showSlots();$('saveMessage').textContent='';$('storageMode').textContent=location.protocol==='file:'?'保存先：このファイルを開いたブラウザ内。公開URLや別ブラウザとは別の記録です。':'保存先：現在のURLのブラウザ内。別のURLとは記録が異なります。';$('exportState').disabled=!playing;$('saveDialog').showModal();}
 function showSlots(){
  $('slots').replaceChildren(...[1,2,3].map(i=>{
   const saved=repo.slot(i),el=node('section',undefined,'slot');el.dataset.slot=i;
   el.append(node('h3',`記録 ${i}`));
   if(saved.state){if(saved.state.civilization)el.append(node('p','文明運営・ターン '+saved.state.civilization.turn+' ／ 都市 '+saved.state.civilization.cities.length));const arc=saved.state.narrative.step,image=node('img',undefined,'thumb');image.src=saved.state.civilization?RokujoCivilizationUI.preview(saved.state.civilization):paths[worldKey(saved.state)];image.alt=saved.state.civilization?'保存した文明の探索範囲と都市の略図':'保存した時点の町';el.append(image);el.append(node('p',saved.state.civilization?`文明運営 · ${RokujoCivilization.status(saved.state.civilization).era}`:`${arc?RokujoStory.chapters[arc].title:E.titles[saved.state.world.stage]} · 観察刻 ${saved.state.world.tick}`),node('p',`${saved.status==='legacy'?'旧試作の記録（原本を残して移行）':'形式2 · '+saved.contentVersion} · ${saved.savedAt}`));}
   else el.append(node('p',saved.status==='empty'?'記録がありません。':saved.reason));
   const actions=node('div',undefined,'slot-actions'),save=node('button','保存'),load=node('button',saved.status==='legacy'?'旧記録から再開':'再開');save.dataset.save=i;load.dataset.load=i;save.disabled=!playing;load.disabled=!saved.state;
   save.onclick=()=>{
    const fresh=repo.slot(i);if(fresh.status!=='empty'&&!confirm(fresh.status==='legacy'?`旧試作の原本を残し、新しい記録 ${i} に保存しますか？`:`記録 ${i} を上書きしますか？`))return;
    try{repo.write(i,state);manualSignature=JSON.stringify(state);showSlots();$('saveMessage').textContent=`記録 ${i} に保存しました。`;if(leaveAfterSave){$('saveDialog').close();toTitle();tell(`記録 ${i} に保存してタイトルへ戻りました。`);}}catch(e){$('saveMessage').textContent=e.message;}
   };
   load.onclick=()=>loadSaved(repo.slot(i),`記録 ${i}`);
   actions.append(save,load);
   if(saved.raw){const out=node('button','元のJSONを書出し');out.onclick=()=>exportRaw(saved.raw,`rokujo-slot-${i}-original.json`);actions.append(out);}
   const legacy=repo.legacy(i);if(!saved.state&&legacy.status==='legacy'){const old=node('button','残っている旧記録から再開');old.onclick=()=>loadSaved(repo.legacy(i),`旧記録 ${i}`);actions.append(old);}
   el.append(actions);return el;
  }));
 }
 function loadSaved(saved,label){if(!saved.state){$('saveMessage').textContent=saved.reason||'記録を読めません。';return;}if(dirty()&&!confirm('未保存の進行を離れて、この記録から再開しますか？'))return;begin(saved.state,true);tell(`${label}から再開しました。時間は停止中です。`);}
 function updateRecoveryButton(){const saved=repo.recovery();$('recover').disabled=!saved.state;}
 const prologue=[['夜中に開いた骨董店','../画像/concept/concept.shop.antique.v1.png','深夜二時過ぎ。ゲーム開発の不調を抱えたソウタは、コンビニ帰りに古い骨董店の灯りへ足を止めた。狭い店には時計、古書、ランプ、見知らぬ部品が並び、奥から老人が声をかける。'],['ガラスの中の、小さな世界','../画像/background/bg.prologue.antique_purchase.v1.png','棚にあったのは、バスケットボールほどのガラス球。森も川も山もある精巧なテラリウムだった。惹かれて見つめるソウタに老人は微笑む。値段はゲームソフト一本ほど。ソウタは、買うと答えていた。'],['六畳間の机から','../画像/background/bg.prologue.first_observation.v1.png','十分後、ソウタは球体を抱えて帰宅する。六畳間の机にはノートパソコン、資料、電子部品、マグカップ。空いた場所にテラリウムを置くと、デスクライトの光が森と川を照らした。ここから、小さな世界を見守る日々が始まる。']];
 // opening-cast-01（Codex納品）の接続。人物入りの背景には立ち絵を重ねず、無人の1頁目だけ人物紹介を並べる。
 // 読込みに失敗したら0.16までの無人コンセプトへ戻し、人物紹介は隠す。進行と保存には影響させない。
 const prologueFallback=[null,'../画像/concept/concept.shop.antique.v1.png','../画像/concept/concept.room.souta.night.v1.png'];
 // 配置の基準は 画像/導入人物_配置メタデータ.json。PNG全体ではなく referenceBodyHeight で身長をそろえ、足元の基準点を下端へ合わせる。
 const prologueCast=[{id:'actor.souta.modern',src:'../画像/actors/actor.souta.modern.v1.png',name:'ソウタ',height:1774,anchorY:1749,body:1717,relative:1},{id:'actor.shopkeeper.antique',src:'../画像/actors/actor.shopkeeper.antique.v1.png',name:'骨董店の店主',height:1536,anchorY:1514,body:1479,relative:0.9}];
 function renderPrologueCast(show){const box=$('prologueCast');box.replaceChildren();box.hidden=!show;if(!show)return;for(const c of prologueCast){const fig=document.createElement('figure'),img=document.createElement('img'),cap=document.createElement('figcaption'),scale=c.relative/c.body;img.alt=c.name;img.dataset.assetId=c.id;img.style.height='calc(var(--cast-body)*'+(c.height*scale).toFixed(4)+')';img.style.marginBottom='calc(var(--cast-body)*'+(-(c.height-c.anchorY)*scale).toFixed(4)+')';img.onerror=()=>{fig.hidden=true;if([...box.children].every(f=>f.hidden))box.hidden=true;};img.src=c.src;cap.textContent=c.name;fig.append(img,cap);box.append(fig);}}
 $('prologueArt').onerror=()=>{const art=$('prologueArt'),fallback=prologueFallback[prologuePage];if(fallback&&art.dataset.fallback!=='1'){art.dataset.fallback='1';art.src=fallback;}};
 let prologuePage=0;
 function showPrologue(){const [title,src,body]=prologue[prologuePage];$('prologueTitle').textContent=title;$('prologueArt').dataset.fallback='0';$('prologueArt').dataset.page=String(prologuePage+1);$('prologueArt').src=src;renderPrologueCast(prologuePage===0);$('prologueText').textContent=body;$('prologuePage').textContent=(prologuePage+1)+' / '+prologue.length+' 頁 · 保存した箱庭は変更しません。';$('prologueNext').textContent=prologuePage===prologue.length-1?'箱庭を覗く':'次の頁';$('prologueDialog').scrollTop=0;}
 $('readPrologue').onclick=()=>{music.resume();prologuePage=0;showPrologue();$('prologueDialog').showModal();$('prologueDialog').scrollTop=0;};$('prologueClose').onclick=()=>$('prologueDialog').close();$('prologueNext').onclick=()=>{if(prologuePage<prologue.length-1){prologuePage++;showPrologue();}else{$('prologueDialog').close();begin(E.create());}};
 const updateMapChoice=()=>{const fixed=$('civilizationMap').value==='observatory';$('civilizationSeedLabel').hidden=fixed;$('civilizationMapNote').textContent=fixed?'原画に沿った固定地形。集落の発見と文明の育ち方は、あなたの行動で変わります。':'世界の種によって地形が変化します。旧版の4地図も引き続き遊べます。';};$('civilizationMap').addEventListener('change',updateMapChoice);updateMapChoice();
$('newCivilization').onclick=()=>{if(dirty()&&!confirm('未保存の進行を離れ、新しい文明を始めますか？'))return;try{const seed=Number($('civilizationSeed').value);const candidate=E.civilizationCommand(E.create(),'start',{seed,map:$('civilizationMap').value,difficulty:$('civilizationDifficulty').value});begin(candidate);}catch(e){tell(e.message);}};
 $('newGame').onclick=()=>{music.resume();if(!dirty()||confirm('未保存の進行を離れ、新しい箱庭を始めますか？'))begin(E.create());};
 $('continue').onclick=()=>{music.resume();openRecords();};$('records').onclick=()=>openRecords();$('recover').onclick=()=>{music.resume();loadSaved(repo.recovery(),'復旧記録');};
 $('step').onclick=()=>{stop();advance();};$('pause').onclick=()=>stop('自動進行を止めました。');$('auto').onclick=toggleAuto;
 $('speed').onchange=()=>{speed=Number($('speed').value);if(auto)schedule();};
 $('confirmSupport').onclick=confirmSupport;$('cancelSupport').onclick=()=>{confirmation=null;$('supportDialog').close();render();};
 $('supportDialog').addEventListener('cancel',()=>{confirmation=null;});
 $('eventDialog').addEventListener('cancel',e=>{if(!replay)e.preventDefault();else replay=null;});$('eventDialog').addEventListener('keydown',e=>{if(e.repeat&&['Enter','Space'].includes(e.code))e.preventDefault();});$('readEvent').onclick=readEvent;$('eventExport').onclick=exportCurrent;
 $('previousPage').onclick=()=>{if(replay){replay.index=Math.max(0,replay.index-1);renderEvent();return;}const e=state?.story.queued[0];if(e?.pages&&(state.story.pageOffsets[e.id]||0)>0){state=E.turnPage(state,e.id,-1);renderEvent();recovery();}};
 $('nextStory').onclick=()=>{if(!playing||modalOpen())return;stop('時間の移り変わりを確認しています。');const info=E.storyNextInfo(state);if(!info.enabled)return;storyConfirmation=state.revision;$('storyAdvanceTitle').textContent=info.title;$('storyElapsed').textContent=info.elapsed;$('storyAdvanceDialog').showModal();$('cancelStory').focus();};
 $('cancelStory').onclick=()=>{storyConfirmation=null;$('storyAdvanceDialog').close();};
 $('confirmStory').onclick=()=>{const revision=storyConfirmation;storyConfirmation=null;if(revision===null)return;try{state=E.advanceStory(state,revision);view='world';$('storyAdvanceDialog').close();render();recovery();showEvent();}catch(e){$('storyAdvanceDialog').close();tell(e.message);}};
 $('storyAdvanceDialog').addEventListener('cancel',()=>{storyConfirmation=null;});
 $('changeView').onclick=()=>{stop('現実と箱庭を切り替えたので、停止しています。');view=view==='room'?'world':'room';clearTimeout(effectTimer);$('waterEffect').hidden=true;render();};
 $('visitResearch').onclick=()=>{if(!playing||state.narrative.step<4)return;stop('研究院を観察しています。');view=view==='workshop'?'world':'workshop';render();};
 $('observationView').onchange=()=>{const next=$('observationView').value;if(!playing||!observationOptions().some(x=>x[0]===next))return;stop('観察先を切り替えています。');view=next;surveyStart=null;surveyMessage='';render();};
 $('civicRecord').onchange=()=>{if(!playing||modalOpen())return;const c=E.civicStatus(state),id=$('civicRecord').value;if(!c.records.some(r=>r.id===id))return;stop('暦と歩みの記録を見ています。');civicSelection=id;renderCivic();};
 $('resetPlanning').onclick=()=>{if(!playing||modalOpen())return;stop('都市模型を最初から試します。');try{state=E.resetPlanning(state,state.revision);render();recovery();document.querySelector('[data-plan-link]')?.focus({preventScroll:true});}catch(e){tell(e.message);}};
 $('cancelSurvey').onclick=()=>{surveyStart=null;surveyMessage='基準点を選び直せます。';renderScholars();};
 $('visitFactory').onclick=()=>{if(!playing||state.narrative.step<21)return;stop('魔導工房を見守っています。');view=['factory','district'].includes(view)?'world':'factory';render();};
 $('visitDistrict').onclick=()=>{if(!playing||state.narrative.step<22||!['factory','district'].includes(view))return;stop('工房の内外を見守っています。');view=view==='district'?'factory':'district';render();};
 document.querySelectorAll('[data-place]').forEach(b=>b.onclick=()=>{selected=b.dataset.place;renderDetail();});
 document.querySelectorAll('[data-library]').forEach(b=>b.onclick=()=>openLibrary(b.dataset.library));$('closeLibrary').onclick=()=>$('libraryDialog').close();
 document.querySelectorAll('[data-jump]').forEach(b=>b.onclick=()=>{stop('画面を確認する間は停止しています。');document.querySelector('.'+b.dataset.jump).scrollIntoView({behavior:settings.motion?'instant':'smooth',block:'start'});});
 $('closeDialog').onclick=()=>{$('saveDialog').close();leaveAfterSave=false;};$('saveDialog').addEventListener('close',()=>{leaveAfterSave=false;});
 $('exportState').onclick=exportCurrent;$('importState').onclick=()=>$('importFile').click();
 $('importFile').onchange=async()=>{
  const file=$('importFile').files[0];$('importFile').value='';if(!file)return;
  if(file.size>4000000){$('saveMessage').textContent='大きすぎる記録です（上限4MB）。';return;}
  const token=++loadingToken,revision=state?.revision;
  try{const raw=await file.text();if(token!==loadingToken||revision!==state?.revision)return;const decoded=repo.decode(raw);if(!decoded.state)throw Error(decoded.reason);loadSaved(decoded,'JSONファイル');}catch(e){$('saveMessage').textContent=e.message;}
 };
 $('settings').onclick=()=>{if(modalOpen())return;stop('設定を確認しています。');applySettings();$('settingsDialog').showModal();};$('closeSettings').onclick=()=>$('settingsDialog').close();$('fontSize').onchange=saveSettings;$('reduceMotion').onchange=saveSettings;
 $('toTitle').onclick=()=>{if(!playing||modalOpen())return;stop();if(dirty())$('leaveDialog').showModal();else toTitle();};
 document.querySelector('.brand').onclick=e=>{e.preventDefault();$('toTitle').click();};
 $('cancelLeave').onclick=()=>$('leaveDialog').close();$('leaveWithout').onclick=toTitle;$('saveAndLeave').onclick=()=>{$('leaveDialog').close();openRecords(true);};
 document.addEventListener('visibilitychange',()=>{if(document.hidden){music.suspend();stop('画面を離れたため停止しました。戻っても自動再開しません。');clearTimeout(effectTimer);$('waterEffect').hidden=true;}});
 document.addEventListener('keydown',e=>{if(e.repeat||!playing||modalOpen()||document.activeElement!==$('world'))return;if(e.code==='Space'){e.preventDefault();stop();}else if(e.code==='ArrowRight'){e.preventDefault();stop();advance();}});
 districtUI=RokujoDistrictUI.create({getState:()=>state,command:(op,params)=>{if(modalOpen())throw Error('今の画面を閉じてください。');stop('街区の計画を確認しています。');state=E.develop(state,op,params,state.revision);render();recovery();}});
 campaignUI=RokujoCampaignUI.create({onChange:syncMusic,getState:()=>state,command:(op,p)=>{stop('人々の物語と共同作業を見守っています。');state=E.campaignCommand(state,op,p,state.revision);render();recovery();}});
 civilizationUI=RokujoCivilizationUI.create({getState:()=>state,onChange:syncMusic,command:(op,p)=>{stop('文明の判断を確認しています。');state=E.civilizationCommand(state,op,p,state.revision);render();recovery();}});
 continuationUI=RokujoContinuation.create({getState:()=>state,command:op=>{stop('原文を読んでいる間は停止しています。');state=E.continueOriginal(state,op,state.revision);render();recovery();}});
 notebook=RokujoNotebook.create({getState:()=>state,onSelect:()=>stop('観測の手帖を読んでいます。')});
 for(const [key,url] of Object.entries(paths)){let im;Object.defineProperty(art,key,{get(){if(!im){im=new Image();im.decoding='async';im.onload=()=>draw();im.onerror=()=>{im.failed=true;draw();tell('画像の一部を読み込めませんでした。画像フォルダの場所を確認してください。');};im.src=url;}return im;}});}
